CREATE OR REPLACE FUNCTION public.apply_credit_reservation(
  p_org_id           uuid,
  p_phase            text,
  p_free_amount      int  DEFAULT 0,
  p_incentive_amount int  DEFAULT 0,
  p_paid_amount      int  DEFAULT 0,
  p_idempotency_key  text DEFAULT NULL,
  p_reference_type   text DEFAULT NULL,
  p_reference_id     text DEFAULT NULL,
  p_note             text DEFAULT NULL,
  p_performed_by     uuid DEFAULT NULL,
  p_parent_id        uuid DEFAULT NULL,
  p_category         text DEFAULT 'paid'
) RETURNS jsonb
LANGUAGE plpgsql
SET search_path = pg_catalog, public
AS $fn$
DECLARE
  v_wallet   organization_credits%ROWTYPE;
  v_tx_row   credit_transactions%ROWTYPE;
  v_avail_free      int;
  v_avail_incentive int;
  v_avail_paid      int;
  v_tx_type  text;
  v_free_delta      int := 0;
  v_incentive_delta int := 0;
  v_paid_delta      int := 0;
BEGIN
  -- ── Idempotency: return existing row if key already processed ───────────────
  IF p_idempotency_key IS NOT NULL THEN
    SELECT * INTO v_tx_row
      FROM credit_transactions
     WHERE idempotency_key = p_idempotency_key
     LIMIT 1;
    IF FOUND THEN
      RETURN row_to_json(v_tx_row)::jsonb;
    END IF;
  END IF;

  -- ── Lock the wallet row for this operation ──────────────────────────────────
  SELECT * INTO v_wallet
    FROM organization_credits
   WHERE organization_id = p_org_id
   FOR UPDATE;

  IF NOT FOUND THEN
    INSERT INTO organization_credits (organization_id)
    VALUES (p_org_id)
    ON CONFLICT (organization_id) DO NOTHING;

    SELECT * INTO v_wallet
      FROM organization_credits
     WHERE organization_id = p_org_id
     FOR UPDATE;
  END IF;

  -- ── Phase dispatch ──────────────────────────────────────────────────────────

  IF p_phase = 'hold' THEN
    v_avail_free      := GREATEST(0, v_wallet.free_balance      - v_wallet.reserved_free);
    v_avail_incentive := GREATEST(0, v_wallet.incentive_balance - v_wallet.reserved_incentive);
    v_avail_paid      := GREATEST(0, v_wallet.paid_balance      - v_wallet.reserved_paid);

    IF p_free_amount > v_avail_free THEN
      RAISE EXCEPTION 'insufficient free balance: need %, have %', p_free_amount, v_avail_free;
    END IF;
    IF p_incentive_amount > v_avail_incentive THEN
      RAISE EXCEPTION 'insufficient incentive balance: need %, have %', p_incentive_amount, v_avail_incentive;
    END IF;
    IF p_paid_amount > v_avail_paid THEN
      RAISE EXCEPTION 'insufficient paid balance: need %, have %', p_paid_amount, v_avail_paid;
    END IF;

    UPDATE organization_credits SET
      free_balance      = free_balance      - p_free_amount,
      incentive_balance = incentive_balance - p_incentive_amount,
      paid_balance      = paid_balance      - p_paid_amount,
      reserved_free     = reserved_free     + p_free_amount,
      reserved_incentive= reserved_incentive+ p_incentive_amount,
      reserved_paid     = reserved_paid     + p_paid_amount,
      updated_at        = NOW()
    WHERE organization_id = p_org_id;

    v_tx_type        := 'deduction';
    v_free_delta     := -p_free_amount;
    v_incentive_delta:= -p_incentive_amount;
    v_paid_delta     := -p_paid_amount;

  ELSIF p_phase = 'confirm' THEN
    UPDATE organization_credits SET
      reserved_free     = GREATEST(0, reserved_free      - p_free_amount),
      reserved_incentive= GREATEST(0, reserved_incentive - p_incentive_amount),
      reserved_paid     = GREATEST(0, reserved_paid      - p_paid_amount),
      lifetime_consumed = lifetime_consumed + p_free_amount + p_incentive_amount + p_paid_amount,
      updated_at        = NOW()
    WHERE organization_id = p_org_id;

    v_tx_type        := 'deduction';
    v_free_delta     := -p_free_amount;
    v_incentive_delta:= -p_incentive_amount;
    v_paid_delta     := -p_paid_amount;

  ELSIF p_phase = 'release' THEN
    UPDATE organization_credits SET
      free_balance      = free_balance      + p_free_amount,
      incentive_balance = incentive_balance + p_incentive_amount,
      paid_balance      = paid_balance      + p_paid_amount,
      reserved_free     = GREATEST(0, reserved_free      - p_free_amount),
      reserved_incentive= GREATEST(0, reserved_incentive - p_incentive_amount),
      reserved_paid     = GREATEST(0, reserved_paid      - p_paid_amount),
      updated_at        = NOW()
    WHERE organization_id = p_org_id;

    v_tx_type        := 'refund';
    v_free_delta     := p_free_amount;
    v_incentive_delta:= p_incentive_amount;
    v_paid_delta     := p_paid_amount;

  ELSIF p_phase = 'grant' THEN
    UPDATE organization_credits SET
      free_balance      = free_balance      + p_free_amount,
      incentive_balance = incentive_balance + p_incentive_amount,
      paid_balance      = paid_balance      + p_paid_amount,
      lifetime_purchased= lifetime_purchased + p_free_amount + p_incentive_amount + p_paid_amount,
      updated_at        = NOW()
    WHERE organization_id = p_org_id;

    v_tx_type        := 'purchase';
    v_free_delta     := p_free_amount;
    v_incentive_delta:= p_incentive_amount;
    v_paid_delta     := p_paid_amount;

  ELSIF p_phase = 'expire' THEN
    -- ── CATEGORY GUARD: expire can only drain free_balance ──────────────────
    -- Paid credits never expire. Incentive credits are expired via a separate
    -- controlled path with explicit config opt-in. Any caller that accidentally
    -- passes non-zero values here gets a hard failure, not a silent no-op.
    IF p_incentive_amount <> 0 THEN
      RAISE EXCEPTION
        'EXPIRY_CATEGORY_GUARD: expire phase cannot touch incentive_balance (p_incentive_amount=%)',
        p_incentive_amount;
    END IF;
    IF p_paid_amount <> 0 THEN
      RAISE EXCEPTION
        'EXPIRY_CATEGORY_GUARD: expire phase cannot touch paid_balance (p_paid_amount=%)',
        p_paid_amount;
    END IF;

    -- Only free_balance is reduced. GREATEST(0, ...) prevents going negative.
    UPDATE organization_credits SET
      free_balance = GREATEST(0, free_balance - p_free_amount),
      updated_at   = NOW()
    WHERE organization_id = p_org_id;

    v_tx_type    := 'deduction';
    v_free_delta := -LEAST(p_free_amount, v_wallet.free_balance);

  ELSIF p_phase = 'expire_incentive' THEN
    -- ── Incentive expiry — separate, explicitly named phase ─────────────────
    -- Only callable when the incentive_expiry config row has is_active=true.
    -- Paid credits are never touched here either.
    IF p_paid_amount <> 0 THEN
      RAISE EXCEPTION
        'EXPIRY_CATEGORY_GUARD: expire_incentive phase cannot touch paid_balance (p_paid_amount=%)',
        p_paid_amount;
    END IF;
    IF p_free_amount <> 0 THEN
      RAISE EXCEPTION
        'EXPIRY_CATEGORY_GUARD: expire_incentive phase cannot touch free_balance (p_free_amount=%)',
        p_free_amount;
    END IF;

    UPDATE organization_credits SET
      incentive_balance = GREATEST(0, incentive_balance - p_incentive_amount),
      updated_at        = NOW()
    WHERE organization_id = p_org_id;

    v_tx_type        := 'deduction';
    v_incentive_delta:= -LEAST(p_incentive_amount, v_wallet.incentive_balance);

  ELSE
    RAISE EXCEPTION 'unknown phase: %', p_phase;
  END IF;

  -- ── Append ledger row ───────────────────────────────────────────────────────
  INSERT INTO credit_transactions (
    organization_id,
    transaction_type,
    credits_delta,
    balance_after,
    reference_type,
    reference_id,
    note,
    performed_by,
    idempotency_key,
    execution_phase,
    parent_transaction_id,
    category,
    free_delta,
    paid_delta,
    incentive_delta,
    created_at
  )
  SELECT
    p_org_id,
    v_tx_type,
    v_free_delta + v_incentive_delta + v_paid_delta,
    oc.free_balance + oc.paid_balance + oc.incentive_balance,
    p_reference_type,
    p_reference_id::uuid,
    p_note,
    p_performed_by,
    p_idempotency_key,
    p_phase,
    p_parent_id,
    p_category,
    v_free_delta,
    v_paid_delta,
    v_incentive_delta,
    NOW()
  FROM organization_credits oc
  WHERE oc.organization_id = p_org_id
  RETURNING * INTO v_tx_row;

  RETURN row_to_json(v_tx_row)::jsonb;

EXCEPTION
  WHEN unique_violation THEN
    SELECT * INTO v_tx_row
      FROM credit_transactions
     WHERE idempotency_key = p_idempotency_key
     LIMIT 1;
    RETURN row_to_json(v_tx_row)::jsonb;
END;
$fn$;
REVOKE ALL ON FUNCTION public.apply_credit_reservation(uuid,text,integer,integer,integer,text,text,text,text,uuid,uuid,text) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.apply_credit_reservation(uuid,text,integer,integer,integer,text,text,text,text,uuid,uuid,text) TO service_role;

CREATE OR REPLACE FUNCTION public.apply_credit_partial_confirm(
  p_org_id uuid,
  p_hold_txn_id uuid,
  p_actual_free int DEFAULT 0,
  p_actual_incentive int DEFAULT 0,
  p_actual_paid int DEFAULT 0,
  p_idempotency_key text DEFAULT NULL,
  p_reference_type text DEFAULT NULL,
  p_reference_id text DEFAULT NULL,
  p_note text DEFAULT NULL,
  p_performed_by uuid DEFAULT NULL
) RETURNS jsonb
LANGUAGE plpgsql
SET search_path = public, extensions
AS $fn$
DECLARE
  v_tx_row       credit_transactions%ROWTYPE;
  v_hold         credit_transactions%ROWTYPE;

  v_held_free       int;
  v_held_incentive  int;
  v_held_paid       int;

  v_consume_free    int;
  v_consume_incentive int;
  v_consume_paid    int;

  v_excess_free     int;
  v_excess_incentive int;
  v_excess_paid     int;

  v_release_free    int;
  v_release_incentive int;
  v_release_paid    int;

  v_wallet          organization_credits%ROWTYPE;
  v_extra_free      int := 0;
  v_extra_incentive int := 0;
  v_extra_paid      int := 0;
  v_shortfall_free  int := 0;
  v_shortfall_incentive int := 0;
  v_shortfall_paid  int := 0;
  v_is_underfunded  boolean := false;

  v_consumed_total  int;
  v_released_total  int;
BEGIN
  -- ── Idempotency ───────────────────────────────────────────────────────────
  IF p_idempotency_key IS NOT NULL THEN
    SELECT * INTO v_tx_row
      FROM credit_transactions
     WHERE idempotency_key = p_idempotency_key
     LIMIT 1;
    IF FOUND THEN
      RETURN row_to_json(v_tx_row)::jsonb;
    END IF;
  END IF;

  -- ── Load and validate parent HOLD ─────────────────────────────────────────
  SELECT * INTO v_hold
    FROM credit_transactions
   WHERE id = p_hold_txn_id
     AND organization_id = p_org_id
     AND execution_phase = 'hold';
  IF NOT FOUND THEN
    RAISE EXCEPTION 'no_hold_found: hold_txn_id=% org=%', p_hold_txn_id, p_org_id;
  END IF;

  -- HOLD deltas are stored NEGATIVE (outflow); flip sign to get held amounts
  v_held_free      := ABS(COALESCE(v_hold.free_delta, 0));
  v_held_incentive := ABS(COALESCE(v_hold.incentive_delta, 0));
  v_held_paid      := ABS(COALESCE(v_hold.paid_delta, 0));

  -- Per-category split:
  --   consume = min(actual, held)
  --   excess  = max(actual - held, 0)   -- needs to come from balance
  --   release = held - consume          -- unused reservation returned
  v_consume_free      := LEAST(p_actual_free,      v_held_free);
  v_consume_incentive := LEAST(p_actual_incentive, v_held_incentive);
  v_consume_paid      := LEAST(p_actual_paid,      v_held_paid);

  v_excess_free       := GREATEST(p_actual_free      - v_held_free,      0);
  v_excess_incentive  := GREATEST(p_actual_incentive - v_held_incentive, 0);
  v_excess_paid       := GREATEST(p_actual_paid      - v_held_paid,      0);

  v_release_free      := v_held_free      - v_consume_free;
  v_release_incentive := v_held_incentive - v_consume_incentive;
  v_release_paid      := v_held_paid      - v_consume_paid;

  -- ── Lock wallet and apply ─────────────────────────────────────────────────
  SELECT * INTO v_wallet
    FROM organization_credits
   WHERE organization_id = p_org_id
   FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'no_credit_account: org %', p_org_id;
  END IF;

  -- 1. Consume from reserved (the "CONFIRM" part):
  --    reserved_X -= consume_X
  --    lifetime_consumed += consume_X
  -- 2. Release unused reservation (the "RELEASE" part):
  --    reserved_X -= release_X
  --    balance_X  += release_X
  -- 3. Excess consumption — try to pull from balance; underfunded if insufficient:
  --    take = min(excess, balance_after_release)
  --    balance_X  -= take
  --    lifetime_consumed += take
  --    shortfall_X = excess - take

  -- Apply (1) + (2) first, then compute excess from updated balance
  UPDATE organization_credits SET
    reserved_free      = GREATEST(0, reserved_free      - v_consume_free      - v_release_free),
    reserved_incentive = GREATEST(0, reserved_incentive - v_consume_incentive - v_release_incentive),
    reserved_paid      = GREATEST(0, reserved_paid      - v_consume_paid      - v_release_paid),
    free_balance       = free_balance      + v_release_free,
    incentive_balance  = incentive_balance + v_release_incentive,
    paid_balance       = paid_balance      + v_release_paid,
    lifetime_consumed  = lifetime_consumed + v_consume_free + v_consume_incentive + v_consume_paid,
    updated_at         = NOW()
  WHERE organization_id = p_org_id
  RETURNING * INTO v_wallet;

  -- (3) Excess from balance
  IF v_excess_free > 0 THEN
    v_extra_free     := LEAST(v_excess_free, v_wallet.free_balance);
    v_shortfall_free := v_excess_free - v_extra_free;
  END IF;
  IF v_excess_incentive > 0 THEN
    v_extra_incentive     := LEAST(v_excess_incentive, v_wallet.incentive_balance);
    v_shortfall_incentive := v_excess_incentive - v_extra_incentive;
  END IF;
  IF v_excess_paid > 0 THEN
    v_extra_paid     := LEAST(v_excess_paid, v_wallet.paid_balance);
    v_shortfall_paid := v_excess_paid - v_extra_paid;
  END IF;

  IF (v_extra_free + v_extra_incentive + v_extra_paid) > 0 THEN
    UPDATE organization_credits SET
      free_balance      = free_balance      - v_extra_free,
      incentive_balance = incentive_balance - v_extra_incentive,
      paid_balance      = paid_balance      - v_extra_paid,
      lifetime_consumed = lifetime_consumed + v_extra_free + v_extra_incentive + v_extra_paid,
      updated_at        = NOW()
    WHERE organization_id = p_org_id;
  END IF;

  v_is_underfunded := (v_shortfall_free + v_shortfall_incentive + v_shortfall_paid) > 0;

  v_consumed_total := v_consume_free + v_consume_incentive + v_consume_paid
                    + v_extra_free   + v_extra_incentive   + v_extra_paid;
  v_released_total := v_release_free + v_release_incentive + v_release_paid;

  -- ── Append ledger row ─────────────────────────────────────────────────────
  INSERT INTO credit_transactions (
    organization_id,
    transaction_type,
    credits_delta,
    balance_after,
    reference_type,
    reference_id,
    note,
    performed_by,
    idempotency_key,
    execution_phase,
    parent_transaction_id,
    category,
    free_delta,
    paid_delta,
    incentive_delta,
    is_underfunded,
    created_at
  )
  VALUES (
    p_org_id,
    'deduction',
    -v_consumed_total,
    (v_wallet.free_balance + v_wallet.paid_balance + v_wallet.incentive_balance)
      - v_extra_free - v_extra_incentive - v_extra_paid,
    p_reference_type,
    p_reference_id::uuid,
    COALESCE(p_note, 'confirm_partial') ||
      CASE WHEN v_is_underfunded
           THEN ' [UNDERFUNDED shortfall_total=' ||
                (v_shortfall_free + v_shortfall_incentive + v_shortfall_paid) || ']'
           ELSE '' END,
    p_performed_by,
    p_idempotency_key,
    'confirm_partial',
    p_hold_txn_id,
    'paid',
    -(v_consume_free      + v_extra_free),
    -(v_consume_paid      + v_extra_paid),
    -(v_consume_incentive + v_extra_incentive),
    v_is_underfunded,
    NOW()
  )
  RETURNING * INTO v_tx_row;

  RETURN jsonb_build_object(
    'id',                 v_tx_row.id,
    'consumed_free',      v_consume_free      + v_extra_free,
    'consumed_incentive', v_consume_incentive + v_extra_incentive,
    'consumed_paid',      v_consume_paid      + v_extra_paid,
    'released_free',      v_release_free,
    'released_incentive', v_release_incentive,
    'released_paid',      v_release_paid,
    'shortfall_free',     v_shortfall_free,
    'shortfall_incentive',v_shortfall_incentive,
    'shortfall_paid',     v_shortfall_paid,
    'is_underfunded',     v_is_underfunded,
    'total_consumed',     v_consumed_total,
    'total_released',     v_released_total
  );

EXCEPTION
  WHEN unique_violation THEN
    SELECT * INTO v_tx_row
      FROM credit_transactions
     WHERE idempotency_key = p_idempotency_key
     LIMIT 1;
    RETURN row_to_json(v_tx_row)::jsonb;
END;
$fn$;
REVOKE ALL ON FUNCTION public.apply_credit_partial_confirm(uuid,uuid,integer,integer,integer,text,text,text,text,uuid) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.apply_credit_partial_confirm(uuid,uuid,integer,integer,integer,text,text,text,text,uuid) TO service_role;

CREATE OR REPLACE FUNCTION public.expire_org_free_credits(
  p_org_id uuid,
  p_amount int,
  p_note   text DEFAULT 'free credit expiry'
) RETURNS int
LANGUAGE plpgsql
SET search_path = pg_catalog, public
AS $fn$
DECLARE
  v_actual int;
BEGIN
  SELECT LEAST(p_amount, free_balance) INTO v_actual
    FROM organization_credits
   WHERE organization_id = p_org_id
   FOR UPDATE;

  IF v_actual IS NULL OR v_actual <= 0 THEN
    RETURN 0;
  END IF;

  UPDATE organization_credits SET
    free_balance = free_balance - v_actual,
    updated_at   = NOW()
  WHERE organization_id = p_org_id;

  RETURN v_actual;
END;
$fn$;
REVOKE ALL ON FUNCTION public.expire_org_free_credits(uuid,integer,text) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.expire_org_free_credits(uuid,integer,text) TO service_role;

DO $verify$
BEGIN
  IF (SELECT md5(prosrc) FROM pg_proc WHERE oid = to_regprocedure('public.apply_credit_reservation(uuid,text,integer,integer,integer,text,text,text,text,uuid,uuid,text)')) <> 'ad5383bf6ccf24a2c8ddee70db3b1297'
     OR (SELECT md5(prosrc) FROM pg_proc WHERE oid = to_regprocedure('public.apply_credit_partial_confirm(uuid,uuid,integer,integer,integer,text,text,text,text,uuid)')) <> 'ff208f60617a7a272305a804037bf47d'
     OR (SELECT md5(prosrc) FROM pg_proc WHERE oid = to_regprocedure('public.expire_org_free_credits(uuid,integer,text)')) <> 'ae410c7ab297eebe2890a7f925d95f04' THEN
    RAISE EXCEPTION '053 rollback: a restored body is not the live one';
  END IF;
END
$verify$;
